Temp File Directory = '\TempDB\'; Temp File Max Size = 256;
Data Source = 'SalesData.sdf';
Password = '<enterStrongPasswordHere>'; File Mode = 'shared read';
Max Database Size = 256; Max Buffer Size = 1024";
